import html.parser
import pprint

def get_collector(convert_charrefs=False):
    return EventCollector(convert_charrefs=convert_charrefs)

def _run_check(source, expected_events, *, collector=None, convert_charrefs=False):
    if collector is None:
        collector = get_collector(convert_charrefs=convert_charrefs)
    parser = collector
    for s in source:
        parser.feed(s)
    parser.close()
    events = parser.get_events()
    if events != expected_events:
        raise AssertionError('received events did not match expected events' + '\nSource:\n' + repr(source) + '\nExpected:\n' + pprint.pformat(expected_events) + '\nReceived:\n' + pprint.pformat(events))

class EventCollector(html.parser.HTMLParser):

    def __init__(self, *args, autocdata=False, **kw):
        self.autocdata = autocdata
        self.events = []
        self.append = self.events.append
        html.parser.HTMLParser.__init__(self, *args, **kw)
        if autocdata:
            self._set_support_cdata(False)

    def get_events(self):
        L = []
        prevtype = None
        for event in self.events:
            type = event[0]
            if type == prevtype == 'data':
                L[-1] = ('data', L[-1][1] + event[1])
            else:
                L.append(event)
            prevtype = type
        self.events = L
        return L

    def handle_starttag(self, tag, attrs):
        self.append(('starttag', tag, attrs))
        if self.autocdata and tag == 'svg':
            self._set_support_cdata(True)

    def handle_startendtag(self, tag, attrs):
        self.append(('startendtag', tag, attrs))

    def handle_endtag(self, tag):
        self.append(('endtag', tag))
        if self.autocdata and tag == 'svg':
            self._set_support_cdata(False)

    def handle_comment(self, data):
        self.append(('comment', data))

    def handle_charref(self, data):
        self.append(('charref', data))

    def handle_data(self, data):
        self.append(('data', data))

    def handle_decl(self, data):
        self.append(('decl', data))

    def handle_entityref(self, data):
        self.append(('entityref', data))

    def handle_pi(self, data):
        self.append(('pi', data))

    def unknown_decl(self, decl):
        self.append(('unknown decl', decl))

def _t():
    _run_check('<form action=bogus|&#()value>', [('starttag', 'form', [('action', 'bogus|&#()value')])])
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')
